-- READ-ONLY aggregate; exact-key source rows absent from reconstruction. UTC fixed bounds.
WITH c AS (SELECT CASE WHEN o.dateTime < 1293840000 THEN 2010 ELSE 2011 END AS utc_year, o.usUnits AS ou, w.usUnits AS wu, o.interval AS oi, w.interval AS wi, o.`soilTemp3` AS old_soilTemp3, w.`soilTemp3` AS wh_soilTemp3, o.`soilTemp4` AS old_soilTemp4, w.`soilTemp4` AS wh_soilTemp4, o.`supplyVoltage` AS old_supplyVoltage, w.`supplyVoltage` AS wh_supplyVoltage, o.`txBatteryStatus` AS old_txBatteryStatus, w.`txBatteryStatus` AS wh_txBatteryStatus, o.`windBatteryStatus` AS old_windBatteryStatus, w.`windBatteryStatus` AS wh_windBatteryStatus, o.`windDir` AS old_windDir, w.`windDir` AS wh_windDir, o.`windGust` AS old_windGust, w.`windGust` AS wh_windGust, o.`windGustDir` AS old_windGustDir, w.`windGustDir` AS wh_windGustDir, o.`windSpeed` AS old_windSpeed, w.`windSpeed` AS wh_windSpeed, o.`windchill` AS old_windchill, w.`windchill` AS wh_windchill
FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime
WHERE o.dateTime >= 1262304000 AND o.dateTime < 1325376000 AND r.dateTime IS NULL)
SELECT utc_year, 'soilTemp3' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilTemp3 IS NOT NULL) AS old_nonnull, SUM(wh_soilTemp3 IS NOT NULL) AS wh_nonnull, SUM(old_soilTemp3 IS NOT NULL AND wh_soilTemp3 IS NOT NULL AND old_soilTemp3 <=> wh_soilTemp3) AS paired_equal, SUM(old_soilTemp3 IS NOT NULL AND wh_soilTemp3 IS NOT NULL AND NOT(old_soilTemp3 <=> wh_soilTemp3)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilTemp4' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilTemp4 IS NOT NULL) AS old_nonnull, SUM(wh_soilTemp4 IS NOT NULL) AS wh_nonnull, SUM(old_soilTemp4 IS NOT NULL AND wh_soilTemp4 IS NOT NULL AND old_soilTemp4 <=> wh_soilTemp4) AS paired_equal, SUM(old_soilTemp4 IS NOT NULL AND wh_soilTemp4 IS NOT NULL AND NOT(old_soilTemp4 <=> wh_soilTemp4)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'supplyVoltage' AS field_name, COUNT(*) AS source_only_rows, SUM(old_supplyVoltage IS NOT NULL) AS old_nonnull, SUM(wh_supplyVoltage IS NOT NULL) AS wh_nonnull, SUM(old_supplyVoltage IS NOT NULL AND wh_supplyVoltage IS NOT NULL AND old_supplyVoltage <=> wh_supplyVoltage) AS paired_equal, SUM(old_supplyVoltage IS NOT NULL AND wh_supplyVoltage IS NOT NULL AND NOT(old_supplyVoltage <=> wh_supplyVoltage)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'txBatteryStatus' AS field_name, COUNT(*) AS source_only_rows, SUM(old_txBatteryStatus IS NOT NULL) AS old_nonnull, SUM(wh_txBatteryStatus IS NOT NULL) AS wh_nonnull, SUM(old_txBatteryStatus IS NOT NULL AND wh_txBatteryStatus IS NOT NULL AND old_txBatteryStatus <=> wh_txBatteryStatus) AS paired_equal, SUM(old_txBatteryStatus IS NOT NULL AND wh_txBatteryStatus IS NOT NULL AND NOT(old_txBatteryStatus <=> wh_txBatteryStatus)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'windBatteryStatus' AS field_name, COUNT(*) AS source_only_rows, SUM(old_windBatteryStatus IS NOT NULL) AS old_nonnull, SUM(wh_windBatteryStatus IS NOT NULL) AS wh_nonnull, SUM(old_windBatteryStatus IS NOT NULL AND wh_windBatteryStatus IS NOT NULL AND old_windBatteryStatus <=> wh_windBatteryStatus) AS paired_equal, SUM(old_windBatteryStatus IS NOT NULL AND wh_windBatteryStatus IS NOT NULL AND NOT(old_windBatteryStatus <=> wh_windBatteryStatus)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'windDir' AS field_name, COUNT(*) AS source_only_rows, SUM(old_windDir IS NOT NULL) AS old_nonnull, SUM(wh_windDir IS NOT NULL) AS wh_nonnull, SUM(old_windDir IS NOT NULL AND wh_windDir IS NOT NULL AND old_windDir <=> wh_windDir) AS paired_equal, SUM(old_windDir IS NOT NULL AND wh_windDir IS NOT NULL AND NOT(old_windDir <=> wh_windDir)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'windGust' AS field_name, COUNT(*) AS source_only_rows, SUM(old_windGust IS NOT NULL) AS old_nonnull, SUM(wh_windGust IS NOT NULL) AS wh_nonnull, SUM(old_windGust IS NOT NULL AND wh_windGust IS NOT NULL AND old_windGust <=> wh_windGust) AS paired_equal, SUM(old_windGust IS NOT NULL AND wh_windGust IS NOT NULL AND NOT(old_windGust <=> wh_windGust)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'windGustDir' AS field_name, COUNT(*) AS source_only_rows, SUM(old_windGustDir IS NOT NULL) AS old_nonnull, SUM(wh_windGustDir IS NOT NULL) AS wh_nonnull, SUM(old_windGustDir IS NOT NULL AND wh_windGustDir IS NOT NULL AND old_windGustDir <=> wh_windGustDir) AS paired_equal, SUM(old_windGustDir IS NOT NULL AND wh_windGustDir IS NOT NULL AND NOT(old_windGustDir <=> wh_windGustDir)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'windSpeed' AS field_name, COUNT(*) AS source_only_rows, SUM(old_windSpeed IS NOT NULL) AS old_nonnull, SUM(wh_windSpeed IS NOT NULL) AS wh_nonnull, SUM(old_windSpeed IS NOT NULL AND wh_windSpeed IS NOT NULL AND old_windSpeed <=> wh_windSpeed) AS paired_equal, SUM(old_windSpeed IS NOT NULL AND wh_windSpeed IS NOT NULL AND NOT(old_windSpeed <=> wh_windSpeed)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'windchill' AS field_name, COUNT(*) AS source_only_rows, SUM(old_windchill IS NOT NULL) AS old_nonnull, SUM(wh_windchill IS NOT NULL) AS wh_nonnull, SUM(old_windchill IS NOT NULL AND wh_windchill IS NOT NULL AND old_windchill <=> wh_windchill) AS paired_equal, SUM(old_windchill IS NOT NULL AND wh_windchill IS NOT NULL AND NOT(old_windchill <=> wh_windchill)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year
ORDER BY utc_year, field_name;
